package com.codepathacademy.curriculum;
import java.util.*; import jakarta.persistence.*; import org.springframework.data.jpa.repository.JpaRepository;
interface TopicRepository extends JpaRepository<Topic,UUID>{Optional<Topic> findByCode(String code); List<Topic> findByParentIdOrderBySortOrder(UUID parentId);}
interface ClassTopicRepository extends JpaRepository<ClassTopicLink,ClassTopicLink.Key>{List<ClassTopicLink> findByCurriculumClassIdOrderBySortOrder(UUID classId);}
interface LessonContentRepository extends JpaRepository<LessonContent,UUID>{Optional<LessonContent> findByCurriculumClassId(UUID classId);}
@Entity @Table(name="class_topics") class ClassTopicLink { @EmbeddedId Key id; @ManyToOne(fetch=FetchType.LAZY) @MapsId("classId") @JoinColumn(name="class_id") CurriculumClass curriculumClass; @ManyToOne(fetch=FetchType.LAZY) @MapsId("topicId") @JoinColumn(name="topic_id") Topic topic; @Column(name="sort_order") int sortOrder; protected ClassTopicLink(){} ClassTopicLink(CurriculumClass c,Topic t,int order){id=new Key(c.getId(),t.getId());curriculumClass=c;topic=t;sortOrder=order;} Topic getTopic(){return topic;} public static class Key implements java.io.Serializable { UUID classId; UUID topicId; protected Key(){} Key(UUID c,UUID t){classId=c;topicId=t;} @Override public boolean equals(Object other){return other instanceof Key key && java.util.Objects.equals(classId,key.classId)&&java.util.Objects.equals(topicId,key.topicId);}@Override public int hashCode(){return java.util.Objects.hash(classId,topicId);} } }
